<script setup lang="ts">
import type { EChartsCoreOption } from "echarts/core";
import { formatMoneyWithSymbol } from "~/utils/currency";
import { appNavItems } from "~/utils/app-nav";
import { formatAppDateTime } from "~/utils/date-format";

type Comparison={value:number|null;available:boolean};type Preset="today"|"yesterday"|"this_week"|"last_week"|"this_month"|"last_month"|"custom";
type Dashboard={currency:string;generated_at:string;period:{from:string;to:string;date_from:string;date_to:string;days:number};summary:{revenue:number;gross_sales:number;discount:number;discount_rate_percent:number;discounted_bill_count:number;vat_amount:number;shipping_revenue:number;shipping_cost:number;bill_count:number;average_bill:number;cancelled_refunded_count:number;cancelled_refunded_amount:number;gross_profit:number;gross_margin_percent:number;comparison:Record<string,Comparison>};profitability:{known_cost:number;known_gross_profit:number;gross_margin_percent:number;cost_coverage_percent:number;unknown_cost_revenue:number;unknown_cost_bills:number};sales_series:Array<{label:string;revenue:number;gross_sales:number;discount:number;vat_amount:number;bill_count:number;known_cost:number;gross_profit:number;unknown_cost_revenue:number}>;payment_mix:Array<{method:string;amount:number;bill_count:number;percent:number}>;top_products:Array<{id:string;name:string;sku:string;quantity:number;revenue:number;percent:number;comparison:Comparison}>;product_mix:Array<{id:string;name:string;revenue:number;quantity:number;percent:number}>;category_performance:Array<{id:string;name:string;quantity:number;revenue:number;known_cost:number;gross_profit:number;margin:number;cost_coverage_percent:number}>;order_type_mix:Array<{type:string;revenue:number;bill_count:number}>;order_type_series:Array<{label:string;type:string;revenue:number;bill_count:number}>;heatmap:Array<{weekday:number;hour:number;revenue:number;bill_count:number}>;staff_ranking:Array<{id:string;name:string;bill_count:number;revenue:number;average_bill:number}>;low_stock:Array<{id:string;name:string;sku:string;available_base:number;threshold:number}>;operational_signals:{peak_period:string|null;peak_revenue:number;primary_payment_method:string|null;primary_payment_percent:number;restock_sku_count:number;out_of_stock_count:number;negative_stock_count:number;no_sales_count:number;inventory_value:number}};
type ProductRow={id:string;name:string;sku:string;category_name:string;quantity:number;average_price:number;revenue:number;known_cost:number;gross_profit:number;margin:number;bill_count:number;comparison:Comparison};
type ProductReport={items:ProductRow[];categories:Array<{id:string;name:string}>;pagination:{page:number;limit:number;total:number;pages:number}};
const {apiFetch}=useApiClient(),{currentStoreId}=useAuthSession(),{locale,t}=useI18n();
const appLocale=computed(()=>locale.value as "th"|"lo"|"en");
const activePreset=ref<Preset>("today"),activeView=ref<"sales"|"products"|"operations">("sales"),dateFrom=ref(""),dateTo=ref("");const dashboard=ref<Dashboard|null>(null),loading=ref(false),errorMessage=ref(""),version=ref(0);
const productMetric=ref<"revenue"|"quantity">("revenue"),productShareMetric=ref<"revenue"|"quantity">("revenue"),heatMetric=ref<"revenue"|"bill_count">("revenue"),productReport=ref<ProductReport|null>(null),productLoading=ref(false),productLoadVersion=ref(0),productSearch=ref(""),productCategory=ref(""),productSort=ref("revenue"),productOrder=ref<"asc"|"desc">("desc"),productPage=ref(1),selectedProduct=ref<ProductRow|null>(null),productTrend=ref<Array<{label:string;quantity:number;revenue:number}>>([]),trendLoading=ref(false);
const dashboardInitialLoading=computed(()=>!dashboard.value&&!errorMessage.value),dashboardRefreshing=computed(()=>loading.value&&Boolean(dashboard.value));
const productsInitialLoading=computed(()=>productLoading.value&&!productReport.value),productsRefreshing=computed(()=>productLoading.value&&Boolean(productReport.value));
const intlLocale=computed(()=>locale.value==="lo"?"lo-LA":locale.value==="en"?"en-US":"th-TH"),money=(value:number)=>formatMoneyWithSymbol(value,dashboard.value?.currency||"LAK",{locale:intlLocale.value,maximumFractionDigits:0}),num=(value:number)=>new Intl.NumberFormat(intlLocale.value,{maximumFractionDigits:2}).format(value);
const presets=computed(()=>[{id:"today",label:t("reportPage.presets.today")},{id:"yesterday",label:t("reportPage.presets.yesterday")},{id:"this_week",label:t("reportPage.presets.thisWeek")},{id:"last_week",label:t("reportPage.presets.lastWeek")},{id:"this_month",label:t("reportPage.presets.thisMonth")},{id:"last_month",label:t("reportPage.presets.lastMonth")},{id:"custom",label:t("reportPage.presets.custom")}] as const);
const paymentLabel=(method:string|null)=>!method?"-":method==="cash"?t("reportPage.cash"):["qr","qr_transfer","transfer","bank_transfer"].includes(method)?t("reportPage.qrTransfer"):["card","credit_card"].includes(method)?t("reportPage.creditCard"):method;
const orderTypeLabel=(type:string)=>["restaurant","dine_in","table"].includes(type)?t("reportPage.dineIn"):["quick_sale","counter","pos"].includes(type)?t("reportPage.quickSale"):type==="other"?t("reportPage.other"):type;
const categoryLabel=(name:string)=>name==="Uncategorized"?t("reportPage.uncategorized"):name;
function query(){const params=new URLSearchParams({store_id:currentStoreId.value||"",preset:activePreset.value,timezone_offset:String(-new Date().getTimezoneOffset())});if(activePreset.value==="custom"){params.set("date_from",dateFrom.value);params.set("date_to",dateTo.value);}return params;}
async function loadDashboard(){if(!currentStoreId.value)return;if(activePreset.value==="custom"&&(!dateFrom.value||!dateTo.value))return;const token=++version.value;loading.value=true;errorMessage.value="";try{const response=await apiFetch<{data:Dashboard}>(`/reports/dashboard?${query()}`);if(token===version.value)dashboard.value=response.data;}catch(error:any){if(token===version.value)errorMessage.value=String(error?.data?.message||error?.message||t("reportPage.loadFailed"));}finally{if(token===version.value)loading.value=false;}}
async function loadProducts(){if(!currentStoreId.value||activeView.value!=="products")return;const token=++productLoadVersion.value;productLoading.value=true;try{const params=query();if(productSearch.value)params.set("search",productSearch.value);if(productCategory.value)params.set("category_id",productCategory.value);params.set("sort",productSort.value);params.set("order",productOrder.value);params.set("page",String(productPage.value));params.set("limit","20");const response=await apiFetch<{data:ProductReport}>(`/reports/products?${params}`);if(token===productLoadVersion.value)productReport.value=response.data;}finally{if(token===productLoadVersion.value)productLoading.value=false;}}
let searchTimer:ReturnType<typeof setTimeout>|undefined;watch([activePreset,dateFrom,dateTo,currentStoreId],()=>void loadDashboard(),{immediate:true});watch([activePreset,dateFrom,dateTo,currentStoreId,activeView,productCategory,productSort,productOrder,productPage],()=>void loadProducts());watch(productSearch,()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{productPage.value=1;void loadProducts();},300);});
async function openProduct(item:ProductRow){selectedProduct.value=item;trendLoading.value=true;try{productTrend.value=(await apiFetch<{data:{items:typeof productTrend.value}}>(`/reports/products/${encodeURIComponent(item.id)}/trend?${query()}`)).data.items;}finally{trendLoading.value=false;}}
const periodText=computed(()=>dashboard.value?dashboard.value.period.date_from===dashboard.value.period.date_to?dashboard.value.period.date_from:`${dashboard.value.period.date_from} – ${dashboard.value.period.date_to}`:"-");
const businessPeriodText=computed(()=>{if(!dashboard.value)return"";const from=new Date(dashboard.value.period.from),to=new Date(new Date(dashboard.value.period.to).getTime()-1);return t("businessPeriod.range",{from:formatAppDateTime(from,appLocale.value),to:formatAppDateTime(to,appLocale.value)});});
const metricCards=computed(()=>dashboard.value?[{label:t("reportPage.netSales"),value:money(dashboard.value.summary.revenue),compare:dashboard.value.summary.comparison.revenue,tone:"emerald"},{label:t("reportPage.billCount"),value:num(dashboard.value.summary.bill_count),compare:dashboard.value.summary.comparison.bill_count,tone:"blue"},{label:t("reportPage.averageBill"),value:money(dashboard.value.summary.average_bill),compare:dashboard.value.summary.comparison.average_bill,tone:"violet"},{label:t("reportPage.cancelRefund"),value:num(dashboard.value.summary.cancelled_refunded_count),compare:dashboard.value.summary.comparison.cancelled_refunded_count,tone:"rose"},{label:t("reportPage.grossProfit"),value:money(dashboard.value.summary.gross_profit),tone:"amber"},{label:t("reportPage.margin"),value:`${dashboard.value.summary.gross_margin_percent.toFixed(1)}%`,tone:"stone"}]:[]);
const salesQualityCards=computed(()=>dashboard.value?[{label:t("reportPage.grossSales"),value:money(dashboard.value.summary.gross_sales),hint:t("reportPage.grossSalesHint")},{label:t("reportPage.discount"),value:money(dashboard.value.summary.discount),hint:t("reportPage.billValue",{value:`${dashboard.value.summary.discount_rate_percent.toFixed(1)}% · ${num(dashboard.value.summary.discounted_bill_count)}`})},{label:"VAT",value:money(dashboard.value.summary.vat_amount),hint:t("reportPage.vatHint")},{label:t("reportPage.cancelRefundValue"),value:money(dashboard.value.summary.cancelled_refunded_amount),hint:t("reportPage.billValue",{value:num(dashboard.value.summary.cancelled_refunded_count)})},{label:t("reportPage.costCoverage"),value:`${dashboard.value.profitability.cost_coverage_percent.toFixed(1)}%`,hint:dashboard.value.profitability.unknown_cost_bills?t("reportPage.incompleteCostBills",{count:num(dashboard.value.profitability.unknown_cost_bills)}):t("reportPage.completeCost")},{label:t("reportPage.inventoryValue"),value:money(dashboard.value.operational_signals.inventory_value),hint:t("reportPage.inventoryValueHint")}]:[]);
const comparisonText=(item?:Comparison)=>item?.available&&item.value!==null?`${item.value>=0?"+":""}${item.value.toFixed(1)}%`:"—";
const commonTooltip={trigger:"axis",backgroundColor:"#fff",borderColor:"#e7e5e4",textStyle:{color:"#292524"}};
const salesOption=computed<EChartsCoreOption>(()=>({color:["#10b981","#3b82f6"],tooltip:commonTooltip,legend:{bottom:0,data:[t("reportPage.sales"),t("reportPage.billCount")]},grid:{left:12,right:18,top:24,bottom:54,containLabel:true},xAxis:{type:"category",data:dashboard.value?.sales_series.map(x=>x.label)||[],axisLine:{lineStyle:{color:"#d6d3d1"}}},yAxis:[{type:"value",axisLabel:{formatter:(v:number)=>Intl.NumberFormat("en",{notation:"compact"}).format(v)},splitLine:{lineStyle:{color:"#f5f5f4"}}},{type:"value",splitLine:{show:false}}],dataZoom:(dashboard.value?.sales_series.length||0)>14?[{type:"inside"},{type:"slider",height:14,bottom:28}]:[],series:[{name:t("reportPage.sales"),type:"line",smooth:true,symbol:"circle",symbolSize:7,areaStyle:{color:"rgba(16,185,129,.14)"},data:dashboard.value?.sales_series.map(x=>x.revenue)||[]},{name:t("reportPage.billCount"),type:"bar",yAxisIndex:1,barMaxWidth:18,itemStyle:{color:"rgba(59,130,246,.35)",borderRadius:[4,4,0,0]},data:dashboard.value?.sales_series.map(x=>x.bill_count)||[]}]}));
const profitOption=computed<EChartsCoreOption>(()=>({color:["#f59e0b","#10b981","#a8a29e"],tooltip:commonTooltip,legend:{bottom:0},grid:{left:10,right:10,top:24,bottom:48,containLabel:true},xAxis:{type:"category",data:dashboard.value?.sales_series.map(x=>x.label)||[]},yAxis:{type:"value",axisLabel:{formatter:(v:number)=>Intl.NumberFormat("en",{notation:"compact"}).format(v)},splitLine:{lineStyle:{color:"#f5f5f4"}}},series:[[t("reportPage.cost"),"known_cost"],[t("reportPage.profit"),"gross_profit"],[t("reportPage.unknownCost"),"unknown_cost_revenue"]].map(([name,key])=>({name,type:"bar",stack:"total",barMaxWidth:26,data:dashboard.value?.sales_series.map(x=>x[key as keyof typeof x])||[]}))}));
const donutOption=computed<EChartsCoreOption>(()=>({color:["#10b981","#3b82f6","#8b5cf6","#f59e0b","#a8a29e"],tooltip:{trigger:"item",formatter:(p:any)=>`${p.name}<br/>${money(p.value)} · ${p.percent}%`},legend:{bottom:0,type:"scroll"},series:[{type:"pie",radius:["48%","72%"],center:["50%","43%"],padAngle:2,itemStyle:{borderRadius:5,borderColor:"#fff",borderWidth:2},label:{show:false},data:dashboard.value?.payment_mix.map(x=>({name:paymentLabel(x.method),value:x.amount}))||[]}]}));
const productOption=computed<EChartsCoreOption>(()=>{const rows=[...(dashboard.value?.top_products||[])].slice(0,8).reverse();return{color:["#10b981"],tooltip:{trigger:"axis",axisPointer:{type:"shadow"}},grid:{left:8,right:24,top:8,bottom:20,containLabel:true},xAxis:{type:"value",splitLine:{lineStyle:{color:"#f5f5f4"}}},yAxis:{type:"category",data:rows.map(x=>x.name),axisLabel:{width:110,overflow:"truncate"}},series:[{type:"bar",barMaxWidth:18,itemStyle:{borderRadius:[0,5,5,0]},data:rows.map(x=>productMetric.value==="revenue"?x.revenue:x.quantity)}]};});
const productShareOption=computed<EChartsCoreOption>(()=>({color:["#10b981","#3b82f6","#8b5cf6","#f59e0b","#ec4899","#06b6d4","#84cc16","#f97316","#a8a29e"],tooltip:{trigger:"item",formatter:(p:any)=>`${p.name}<br/>${productShareMetric.value==="revenue"?money(p.value):t("reportPage.itemValue",{value:num(p.value)})} · ${p.percent}%`},legend:{bottom:0,type:"scroll",formatter:(name:string)=>name==="Other products"?t("reportPage.otherProducts"):name},series:[{type:"pie",radius:["48%","72%"],center:["50%","43%"],padAngle:2,itemStyle:{borderRadius:5,borderColor:"#fff",borderWidth:2},label:{show:false},data:dashboard.value?.product_mix.map(x=>({name:x.name==="Other products"?t("reportPage.otherProducts"):x.name,value:productShareMetric.value==="revenue"?x.revenue:x.quantity}))||[]}]}));
const categoryOption=computed<EChartsCoreOption>(()=>{const rows=[...(dashboard.value?.category_performance||[])].slice(0,8).reverse();return{color:["#3b82f6","#10b981"],tooltip:{trigger:"axis",axisPointer:{type:"shadow"},valueFormatter:(value:any)=>money(Number(value))},legend:{bottom:0},grid:{left:8,right:18,top:16,bottom:44,containLabel:true},xAxis:{type:"value",axisLabel:{formatter:(v:number)=>Intl.NumberFormat("en",{notation:"compact"}).format(v)},splitLine:{lineStyle:{color:"#f5f5f4"}}},yAxis:{type:"category",data:rows.map(x=>categoryLabel(x.name)),axisLabel:{width:120,overflow:"truncate"}},series:[{name:t("reportPage.revenue"),type:"bar",barMaxWidth:16,data:rows.map(x=>x.revenue)},{name:t("reportPage.calculatedProfit"),type:"bar",barMaxWidth:16,data:rows.map(x=>x.gross_profit)}]};});
const discountOption=computed<EChartsCoreOption>(()=>({color:["#10b981","#f59e0b"],tooltip:{trigger:"axis",valueFormatter:(value:any)=>money(Number(value))},legend:{bottom:0},grid:{left:10,right:16,top:20,bottom:48,containLabel:true},xAxis:{type:"category",data:dashboard.value?.sales_series.map(x=>x.label)||[]},yAxis:{type:"value",axisLabel:{formatter:(v:number)=>Intl.NumberFormat("en",{notation:"compact"}).format(v)},splitLine:{lineStyle:{color:"#f5f5f4"}}},series:[{name:t("reportPage.netSales"),type:"line",smooth:true,data:dashboard.value?.sales_series.map(x=>x.revenue)||[]},{name:t("reportPage.discount"),type:"bar",barMaxWidth:18,data:dashboard.value?.sales_series.map(x=>x.discount)||[]}]}));
const orderOption=computed<EChartsCoreOption>(()=>{const labels=dashboard.value?.sales_series.map(x=>x.label)||[],types=[...new Set(dashboard.value?.order_type_series.map(x=>x.type)||[])];return{color:["#10b981","#3b82f6","#8b5cf6","#f59e0b"],tooltip:{trigger:"axis",axisPointer:{type:"shadow"}},legend:{bottom:0},grid:{left:8,right:16,top:28,bottom:48,containLabel:true},xAxis:{type:"category",data:labels},yAxis:{type:"value",splitLine:{lineStyle:{color:"#f5f5f4"}}},series:types.map(type=>({name:orderTypeLabel(type),type:"bar",stack:"orders",barMaxWidth:26,data:labels.map(label=>dashboard.value?.order_type_series.find(x=>x.label===label&&x.type===type)?.revenue||0)}))};});
const heatOption=computed<EChartsCoreOption>(()=>{const values=dashboard.value?.heatmap.map(x=>[x.hour,x.weekday,heatMetric.value==="revenue"?x.revenue:x.bill_count])||[],max=Math.max(1,...values.map(x=>Number(x[2]))),weekdays=Array.from({length:7},(_,index)=>t(`reportPage.weekdays.${index}`));return{tooltip:{formatter:(p:any)=>`${weekdays[p.value[1]]} ${String(p.value[0]).padStart(2,"0")}:00<br/>${heatMetric.value==="revenue"?money(p.value[2]):t("reportPage.billValue",{value:p.value[2]})}`},grid:{left:12,right:20,top:10,bottom:42,containLabel:true},xAxis:{type:"category",data:Array.from({length:24},(_,i)=>String(i).padStart(2,"0")),splitArea:{show:true}},yAxis:{type:"category",data:weekdays,splitArea:{show:true}},visualMap:{min:0,max,calculable:false,orient:"horizontal",left:"center",bottom:0,inRange:{color:["#ecfdf5","#6ee7b7","#059669"]}},series:[{type:"heatmap",data:values,itemStyle:{borderColor:"#fff",borderWidth:2}}]};});
const trendOption=computed<EChartsCoreOption>(()=>({color:["#10b981"],tooltip:commonTooltip,grid:{left:8,right:12,top:16,bottom:28,containLabel:true},xAxis:{type:"category",data:productTrend.value.map(x=>x.label)},yAxis:{type:"value",splitLine:{lineStyle:{color:"#f5f5f4"}}},series:[{type:"line",smooth:true,areaStyle:{color:"rgba(16,185,129,.14)"},data:productTrend.value.map(x=>x.revenue)}]}));
</script>

<template><AppSidebarShell :nav-items="appNavItems" :active-ids="['reports']" :sidebar-eyebrow="t('reportPage.eyebrow')" :sidebar-title="t('reportPage.title')" sidebar-compact-title="REP" :sidebar-description="t('reportPage.sidebarDescription')"><template #default="{openSidebar}"><div class="grid w-full min-w-0 max-w-full gap-3 overflow-x-hidden pb-4">
	<AppPageHeader :title-badge="false" compact title="" body-class="px-3 py-2.5 sm:px-4 sm:py-3" @menu="openSidebar"><div class="flex min-h-10 items-center justify-between gap-3"><div class="min-w-0"><div class="flex min-w-0 items-baseline gap-2"><h1 class="shrink-0 text-base font-semibold tracking-[-0.02em] text-stone-950">{{t('reportPage.title')}}</h1><span class="truncate text-sm font-medium text-stone-600">{{periodText}}</span></div><p class="mt-0.5 text-xs text-stone-400">{{t('reportPage.updated')}} {{dashboard?.generated_at?new Date(dashboard.generated_at).toLocaleTimeString(intlLocale):'-'}}</p></div><AppButton icon="i-heroicons-arrow-path-20-solid" color="neutral" variant="soft" size="md" class="shrink-0 self-center rounded-md" :label="t('reportPage.reload')" :loading="loading" :spin-icon-on-loading="true" @click="loadDashboard"/></div></AppPageHeader>
	<div class="relative min-w-0 overflow-hidden rounded-md border border-stone-200 bg-white p-3 shadow-sm"><div class="grid grid-cols-3 gap-2 sm:flex sm:overflow-x-auto sm:pb-1"><AppButton v-for="preset in presets" :key="preset.id" :color="activePreset===preset.id?'primary':'neutral'" :variant="activePreset===preset.id?'solid':'soft'" :label="preset.label" class="min-w-0 justify-center sm:shrink-0" @click="activePreset=preset.id"/></div><div v-if="activePreset==='custom'" class="mt-3 grid min-w-0 gap-2 sm:grid-cols-[1fr_1fr_auto]"><input v-model="dateFrom" type="date" class="min-w-0 rounded-md border border-stone-300 px-3 py-2 text-sm"><input v-model="dateTo" type="date" class="min-w-0 rounded-md border border-stone-300 px-3 py-2 text-sm"><AppButton color="primary" :label="t('reportPage.apply')" @click="loadDashboard"/></div><div v-if="businessPeriodText" class="mt-3 flex items-start gap-2 rounded-md bg-sky-50 px-3 py-2 text-xs text-sky-800"><UIcon name="i-lucide-clock-3" class="mt-0.5 size-4 shrink-0"/><span class="leading-5">{{ businessPeriodText }}</span></div><AppInlineLoadingBar v-if="dashboardRefreshing" class="pointer-events-none absolute inset-x-0 bottom-0 z-10" minimal container-class="bg-transparent" /></div>
	<div v-if="dashboardInitialLoading" class="space-y-3" aria-busy="true" :aria-label="t('reportPage.loading')">
		<div class="grid grid-cols-2 gap-3 px-2 sm:px-0 xl:grid-cols-6"><div v-for="i in 6" :key="`metric-${i}`" class="h-24 rounded-md border border-stone-200 bg-white p-3 shadow-sm sm:p-4"><USkeleton class="h-3 w-20 max-w-[65%] rounded-full"/><USkeleton class="mt-4 h-6 w-28 max-w-[85%] rounded-md"/></div></div>
		<div class="grid h-12 grid-cols-3 gap-2 rounded-md border border-stone-200 bg-white p-2"><USkeleton v-for="i in 3" :key="`tab-${i}`" class="rounded-md"/></div>
		<div class="grid gap-3 xl:grid-cols-[1.4fr_.6fr]"><div v-for="i in 2" :key="`chart-${i}`" class="h-80 rounded-md border border-stone-200 bg-white p-4 shadow-sm"><USkeleton class="h-4 w-36 max-w-[55%] rounded-full"/><USkeleton class="mt-6 h-[230px] w-full rounded-md"/></div></div>
	</div><div v-else-if="errorMessage" class="rounded-md border border-rose-200 bg-rose-50 p-8 text-center"><p class="font-semibold text-rose-900">{{errorMessage}}</p><AppButton class="mt-4" :label="t('reportPage.tryAgain')" @click="loadDashboard"/></div>
	<template v-else-if="dashboard"><div class="grid min-w-0 grid-cols-2 gap-3 px-2 [&>*]:min-w-0 sm:px-0 xl:grid-cols-6"><div v-for="card in metricCards" :key="card.label" class="min-w-0 rounded-md border border-stone-200 bg-white p-3 shadow-sm sm:p-4"><div class="flex min-w-0 items-start justify-between gap-1 sm:gap-2"><p class="min-w-0 truncate text-xs font-semibold text-stone-500">{{card.label}}</p><span v-if="card.compare" class="shrink-0 rounded-full bg-stone-50 px-1.5 py-0.5 text-[9px] sm:px-2 sm:text-[10px]" :class="card.compare.value!==null&&card.compare.value>=0?'text-emerald-700':'text-rose-700'">{{comparisonText(card.compare)}}</span></div><p class="mt-2 truncate text-lg font-semibold text-stone-950 sm:text-2xl">{{card.value}}</p></div></div>
	<div class="grid min-w-0 grid-cols-2 gap-2 px-2 [&>*]:min-w-0 sm:px-0 xl:grid-cols-6"><div v-for="card in salesQualityCards" :key="card.label" class="min-w-0 rounded-md border border-stone-200 bg-white p-3 shadow-sm"><p class="truncate text-[11px] font-semibold uppercase tracking-wide text-stone-500">{{card.label}}</p><p class="mt-1 truncate text-base font-semibold tabular-nums text-stone-950 sm:text-lg">{{card.value}}</p><p class="mt-1 truncate text-[11px] text-stone-500" :title="card.hint">{{card.hint}}</p></div></div>
	<div class="grid min-w-0 grid-cols-3 gap-1 rounded-md border border-stone-200 bg-white p-2 sm:flex sm:gap-2"><AppButton v-for="tab in [{id:'sales',label:t('reportPage.sales')},{id:'products',label:t('reportPage.products')},{id:'operations',label:t('reportPage.operations')}]" :key="tab.id" class="min-w-0 justify-center" :color="activeView===tab.id?'primary':'neutral'" :variant="activeView===tab.id?'solid':'ghost'" :label="tab.label" @click="activeView=tab.id as any"/></div>
	<template v-if="activeView==='sales'"><div class="grid gap-3 xl:grid-cols-[1.4fr_.6fr]"><UCard><h2 class="font-semibold">{{t('reportPage.salesTrend')}}</h2><ReportsReportChart :option="salesOption" :empty="!dashboard.sales_series.some(x=>x.revenue)"/></UCard><UCard><h2 class="font-semibold">{{t('reportPage.paymentMix')}}</h2><ReportsReportChart :option="donutOption" :empty="!dashboard.payment_mix.length"/></UCard></div><div class="grid gap-3 xl:grid-cols-3"><UCard><div class="flex justify-between"><h2 class="font-semibold">{{t('reportPage.revenueCostProfit')}}</h2><span v-if="dashboard.profitability.unknown_cost_bills" class="text-xs text-amber-700" :title="t('reportPage.incompleteCostBills',{count:dashboard.profitability.unknown_cost_bills})">⚠ {{t('reportPage.incompleteCost')}}</span></div><ReportsReportChart :option="profitOption" :empty="!dashboard.sales_series.some(x=>x.revenue)"/></UCard><UCard><h2 class="font-semibold">{{t('reportPage.salesByOrderType')}}</h2><ReportsReportChart :option="orderOption" :empty="!dashboard.order_type_mix.length"/></UCard><UCard><h2 class="font-semibold">{{t('reportPage.salesAndDiscount')}}</h2><ReportsReportChart :option="discountOption" :empty="!dashboard.sales_series.some(x=>x.revenue||x.discount)"/></UCard></div></template>
	<template v-else-if="activeView==='products'"><div class="grid min-w-0 gap-3 [&>*]:min-w-0 xl:grid-cols-2"><UCard><div class="flex flex-col items-start gap-2 sm:flex-row sm:items-center sm:justify-between"><h2 class="font-semibold">{{t('reportPage.bestSellers')}}</h2><div class="flex gap-1"><AppButton size="xs" :variant="productMetric==='revenue'?'solid':'soft'" :label="t('reportPage.revenue')" @click="productMetric='revenue'"/><AppButton size="xs" :variant="productMetric==='quantity'?'solid':'soft'" :label="t('reportPage.quantity')" @click="productMetric='quantity'"/></div></div><ReportsReportChart :option="productOption" :empty="!dashboard.top_products.length"/></UCard><UCard><div class="flex flex-col items-start gap-2 sm:flex-row sm:justify-between sm:gap-3"><div class="min-w-0"><h2 class="font-semibold">{{t('reportPage.productSalesMix')}}</h2><p class="mt-1 text-xs text-stone-500">{{t('reportPage.productSalesMixHint')}}</p></div><div class="flex shrink-0 gap-1"><AppButton size="xs" :variant="productShareMetric==='revenue'?'solid':'soft'" :label="t('reportPage.revenue')" @click="productShareMetric='revenue'"/><AppButton size="xs" :variant="productShareMetric==='quantity'?'solid':'soft'" :label="t('reportPage.quantity')" @click="productShareMetric='quantity'"/></div></div><ReportsReportChart :option="productShareOption" :empty="!dashboard.product_mix.some(x=>productShareMetric==='revenue'?x.revenue:x.quantity)"/></UCard></div>
	<div class="grid gap-3 xl:grid-cols-2"><UCard><h2 class="font-semibold">{{t('reportPage.categoryRevenueProfit')}}</h2><ReportsReportChart :option="categoryOption" :empty="!dashboard.category_performance.length"/></UCard><UCard><h2 class="font-semibold">{{t('reportPage.restockProducts')}}</h2><div v-if="dashboard.low_stock.length" class="mt-4 grid gap-2 sm:grid-cols-2"><div v-for="item in dashboard.low_stock" :key="item.id" class="rounded-md border border-amber-200 bg-amber-50 p-3"><p class="truncate font-semibold">{{item.name}}</p><div class="mt-1 flex justify-between text-xs"><span>{{item.sku}}</span><strong class="text-amber-800">{{num(item.available_base)}} / {{num(item.threshold)}}</strong></div></div></div><p v-else class="py-16 text-center text-sm text-stone-500">{{t('reportPage.stockNormal')}}</p></UCard></div>
	<UCard><div class="flex items-center justify-between gap-3"><div><h2 class="font-semibold">{{t('reportPage.categoryDetails')}}</h2><p class="text-xs text-stone-500">{{t('reportPage.profitCoverageHint')}}</p></div><span class="rounded-full bg-stone-100 px-2.5 py-1 text-xs text-stone-600">{{t('reportPage.categoryCount',{count:dashboard.category_performance.length})}}</span></div><div class="mt-4 overflow-x-auto"><table class="min-w-[760px] w-full text-sm"><thead class="bg-stone-50 text-left text-xs text-stone-500"><tr><th class="p-3">{{t('reportPage.category')}}</th><th class="p-3 text-right">{{t('reportPage.quantity')}}</th><th class="p-3 text-right">{{t('reportPage.revenue')}}</th><th class="p-3 text-right">{{t('reportPage.cost')}}</th><th class="p-3 text-right">{{t('reportPage.profit')}}</th><th class="p-3 text-right">{{t('reportPage.margin')}}</th><th class="p-3 text-right">{{t('reportPage.costCoverage')}}</th></tr></thead><tbody><tr v-for="category in dashboard.category_performance" :key="category.id" class="border-t border-stone-100"><td class="p-3 font-semibold">{{categoryLabel(category.name)}}</td><td class="p-3 text-right">{{num(category.quantity)}}</td><td class="p-3 text-right font-semibold">{{money(category.revenue)}}</td><td class="p-3 text-right">{{money(category.known_cost)}}</td><td class="p-3 text-right text-emerald-700">{{money(category.gross_profit)}}</td><td class="p-3 text-right">{{category.margin.toFixed(1)}}%</td><td class="p-3 text-right" :class="category.cost_coverage_percent<100?'text-amber-700':'text-stone-700'">{{category.cost_coverage_percent.toFixed(1)}}%</td></tr></tbody></table></div></UCard>
	<UCard class="relative overflow-hidden"><AppInlineLoadingBar v-if="productsRefreshing" class="pointer-events-none absolute inset-x-0 top-0 z-10" minimal container-class="bg-transparent" /><div class="flex flex-wrap items-center justify-between gap-2"><div><h2 class="font-semibold">{{t('reportPage.allProductReport')}}</h2><p class="text-xs text-stone-500">{{t('reportPage.productsInPeriod',{count:productReport?.pagination.total||0})}}</p></div><div class="flex flex-wrap gap-2"><input v-model="productSearch" :placeholder="t('reportPage.searchProduct')" class="min-w-0 flex-1 rounded-md border border-stone-300 px-3 py-2 text-sm"><select v-model="productCategory" class="rounded-md border border-stone-300 px-3 py-2 text-sm"><option value="">{{t('reportPage.allCategories')}}</option><option v-for="category in productReport?.categories" :key="category.id" :value="category.id">{{categoryLabel(category.name)}}</option></select><select v-model="productSort" class="rounded-md border border-stone-300 px-3 py-2 text-sm"><option value="revenue">{{t('reportPage.revenue')}}</option><option value="quantity">{{t('reportPage.quantitySold')}}</option><option value="average_price">{{t('reportPage.averagePrice')}}</option><option value="cost">{{t('reportPage.cost')}}</option><option value="profit">{{t('reportPage.profit')}}</option><option value="margin">{{t('reportPage.margin')}}</option></select><AppButton color="neutral" variant="soft" :icon="productOrder==='desc'?'i-heroicons-bars-arrow-down':'i-heroicons-bars-arrow-up'" :label="t(productOrder==='desc'?'reportPage.highToLow':'reportPage.lowToHigh')" @click="productOrder=productOrder==='desc'?'asc':'desc'"/></div></div>
	<div v-if="productsInitialLoading" class="mt-4" aria-busy="true" :aria-label="t('reportPage.loadingProducts')"><div class="space-y-2 md:hidden"><USkeleton v-for="i in 5" :key="`mobile-product-${i}`" class="h-24 rounded-md"/></div><div class="hidden space-y-2 md:block"><USkeleton class="h-10 rounded-md"/><USkeleton v-for="i in 7" :key="`product-row-${i}`" class="h-14 rounded-md"/></div></div>
	<template v-else>
	<div class="mt-4 space-y-2 md:hidden"><button v-for="item in productReport?.items" :key="item.id" class="w-full rounded-md border border-stone-200 p-3 text-left" @click="openProduct(item)"><div class="flex justify-between gap-3"><div class="min-w-0"><p class="truncate font-semibold">{{item.name}}</p><p class="text-xs text-stone-400">{{item.sku}} · {{categoryLabel(item.category_name)}}</p></div><strong class="text-emerald-700">{{money(item.revenue)}}</strong></div><div class="mt-3 grid grid-cols-3 gap-2 text-xs"><span>{{t('reportPage.sold')}} <b>{{num(item.quantity)}}</b></span><span>{{t('reportPage.profit')}} <b>{{money(item.gross_profit)}}</b></span><span>{{t('reportPage.margin')}} <b>{{item.margin.toFixed(1)}}%</b></span></div></button></div>
	<div class="mt-4 hidden overflow-x-auto md:block"><table class="min-w-[1050px] w-full text-sm"><thead class="bg-stone-50 text-left text-xs text-stone-500"><tr><th class="p-3">{{t('reportPage.product')}}</th><th class="p-3">{{t('reportPage.category')}}</th><th class="p-3 text-right">{{t('reportPage.quantity')}}</th><th class="p-3 text-right">{{t('reportPage.averagePrice')}}</th><th class="p-3 text-right">{{t('reportPage.revenue')}}</th><th class="p-3 text-right">{{t('reportPage.cost')}}</th><th class="p-3 text-right">{{t('reportPage.profit')}}</th><th class="p-3 text-right">{{t('reportPage.margin')}}</th><th class="p-3 text-right">{{t('reportPage.bills')}}</th></tr></thead><tbody><tr v-for="item in productReport?.items" :key="item.id" class="cursor-pointer border-t border-stone-100 hover:bg-emerald-50/40" @click="openProduct(item)"><td class="p-3"><strong>{{item.name}}</strong><p class="text-xs text-stone-400">{{item.sku}}</p></td><td class="p-3">{{categoryLabel(item.category_name)}}</td><td class="p-3 text-right">{{num(item.quantity)}}</td><td class="p-3 text-right">{{money(item.average_price)}}</td><td class="p-3 text-right font-semibold">{{money(item.revenue)}}</td><td class="p-3 text-right">{{money(item.known_cost)}}</td><td class="p-3 text-right text-emerald-700">{{money(item.gross_profit)}}</td><td class="p-3 text-right">{{item.margin.toFixed(1)}}%</td><td class="p-3 text-right">{{item.bill_count}}</td></tr></tbody></table></div><div v-if="!productReport?.items.length" class="py-12 text-center text-sm text-stone-500">{{t('reportPage.noProducts')}}</div><div class="mt-3 flex justify-end gap-2"><AppButton color="neutral" variant="soft" :label="t('reportPage.previous')" :disabled="productPage<=1||productLoading" @click="productPage--"/><span class="self-center text-sm">{{productPage}} / {{productReport?.pagination.pages||1}}</span><AppButton color="neutral" variant="soft" :label="t('reportPage.next')" :disabled="productPage>=(productReport?.pagination.pages||1)||productLoading" @click="productPage++"/></div>
	</template></UCard></template>
	<template v-else><div class="grid gap-3 xl:grid-cols-[1.4fr_.6fr]"><UCard><div class="flex justify-between"><h2 class="font-semibold">{{t('reportPage.peakSalesTimes')}}</h2><div class="flex gap-1"><AppButton size="xs" :variant="heatMetric==='revenue'?'solid':'soft'" :label="t('reportPage.revenue')" @click="heatMetric='revenue'"/><AppButton size="xs" :variant="heatMetric==='bill_count'?'solid':'soft'" :label="t('reportPage.bills')" @click="heatMetric='bill_count'"/></div></div><ReportsReportChart :option="heatOption" height="360px" :empty="!dashboard.heatmap.length"/></UCard><UCard><h2 class="font-semibold">{{t('reportPage.operationalSignals')}}</h2><div class="mt-4 space-y-3"><div class="rounded-md bg-emerald-50 p-4"><p class="text-xs text-emerald-700">{{t('reportPage.peakPeriod')}}</p><strong class="mt-1 block text-xl">{{dashboard.operational_signals.peak_period||'-'}}</strong><span class="text-xs">{{money(dashboard.operational_signals.peak_revenue)}}</span></div><div class="rounded-md bg-blue-50 p-4"><p class="text-xs text-blue-700">{{t('reportPage.primaryPayment')}}</p><strong class="mt-1 block text-xl">{{paymentLabel(dashboard.operational_signals.primary_payment_method)}}</strong><span class="text-xs">{{dashboard.operational_signals.primary_payment_percent.toFixed(1)}}%</span></div><div class="rounded-md bg-amber-50 p-4"><p class="text-xs text-amber-700">{{t('reportPage.restockNeeded')}}</p><strong class="mt-1 block text-xl">{{dashboard.operational_signals.restock_sku_count}} SKU</strong></div></div></UCard></div><UCard><h2 class="font-semibold">{{t('reportPage.stockHealth')}}</h2><p class="mt-1 text-xs text-stone-500">{{t('reportPage.stockHealthHint')}}</p><div class="mt-4 grid grid-cols-2 gap-3 lg:grid-cols-4"><div class="rounded-md bg-stone-50 p-4"><p class="text-xs text-stone-500">{{t('reportPage.inventoryValue')}}</p><strong class="mt-1 block text-lg">{{money(dashboard.operational_signals.inventory_value)}}</strong></div><div class="rounded-md bg-rose-50 p-4"><p class="text-xs text-rose-700">{{t('reportPage.outOfStock')}}</p><strong class="mt-1 block text-lg">{{dashboard.operational_signals.out_of_stock_count}} SKU</strong></div><div class="rounded-md bg-red-50 p-4"><p class="text-xs text-red-700">{{t('reportPage.negativeStock')}}</p><strong class="mt-1 block text-lg">{{dashboard.operational_signals.negative_stock_count}} SKU</strong></div><div class="rounded-md bg-amber-50 p-4"><p class="text-xs text-amber-700">{{t('reportPage.noSales')}}</p><strong class="mt-1 block text-lg">{{dashboard.operational_signals.no_sales_count}} SKU</strong></div></div></UCard><UCard><h2 class="font-semibold">{{t('reportPage.staffPerformance')}}</h2><div class="mt-4 grid gap-2 md:grid-cols-2 xl:grid-cols-3"><div v-for="(staff,index) in dashboard.staff_ranking" :key="staff.id" class="flex items-center gap-3 rounded-md border border-stone-200 p-3"><span class="grid h-9 w-9 place-items-center rounded-full bg-emerald-50 font-semibold text-emerald-700">{{index+1}}</span><div class="min-w-0 flex-1"><p class="truncate font-semibold">{{staff.name}}</p><p class="text-xs text-stone-500">{{t('reportPage.staffSummary',{bills:staff.bill_count,average:money(staff.average_bill)})}}</p></div><strong>{{money(staff.revenue)}}</strong></div></div></UCard></template>
	</template></div>
	<div v-if="selectedProduct" class="fixed inset-0 z-50 flex justify-end bg-stone-950/35" @click.self="selectedProduct=null"><aside class="h-full w-full max-w-xl overflow-y-auto bg-white p-5 shadow-2xl"><div class="flex justify-between"><div><h2 class="text-xl font-semibold">{{selectedProduct.name}}</h2><p class="text-sm text-stone-500">{{selectedProduct.sku}} · {{periodText}}</p></div><AppButton icon="i-heroicons-x-mark" color="neutral" variant="soft" @click="selectedProduct=null"/></div><div class="mt-5 grid grid-cols-2 gap-3"><div class="rounded-md bg-stone-50 p-3"><p class="text-xs text-stone-500">{{t('reportPage.revenue')}}</p><strong>{{money(selectedProduct.revenue)}}</strong></div><div class="rounded-md bg-stone-50 p-3"><p class="text-xs text-stone-500">{{t('reportPage.quantitySold')}}</p><strong>{{num(selectedProduct.quantity)}}</strong></div><div class="rounded-md bg-stone-50 p-3"><p class="text-xs text-stone-500">{{t('reportPage.profit')}}</p><strong>{{money(selectedProduct.gross_profit)}}</strong></div><div class="rounded-md bg-stone-50 p-3"><p class="text-xs text-stone-500">{{t('reportPage.margin')}}</p><strong>{{selectedProduct.margin.toFixed(1)}}%</strong></div></div><USkeleton v-if="trendLoading" class="mt-5 h-80 rounded-md"/><ReportsReportChart v-else class="mt-5" :option="trendOption" :empty="!productTrend.length"/></aside></div>
	</template></AppSidebarShell></template>
